-- ---------------------------------------------------------------------------
-- MEMBER-LOADED scope (T, 2025): false-positive guard (case b).
-- This scope has cross-season game rows (PB_01 / PP_01 in OG_SEASON, persp=T)
-- AND stored rows of completeness 'full' -- modelling a team loaded via the
-- member season-stats loader, whose season rows come straight from the API and
-- are NOT summed from games.  The gate must EXCLUDE it: it has stored rows of
-- some completeness (so it is not a "missing aggregate"), and zero
-- boxscore_only rows (so it is not a validated scope).  The stored values here
-- are deliberately NOT the SUM of the 9/99 game rows -- if the gate ever
-- wrongly checked this scope, those non-matching values would surface as a
-- false positive, which test_member_loaded_scope_not_flagged asserts does NOT
-- happen.  (This is ALSO why the cross-season exclusion rows need a home: with
-- the missing-aggregate detection added, an unstored perspective=team scope
-- would otherwise be flagged -- making it member-loaded keeps the green path
-- exact while still probing the recompute's season filter.)
-- ---------------------------------------------------------------------------
INSERT INTO player_season_batting
    (player_id, team_id, season_id, stat_completeness, gp, games_tracked,
     ab, h, doubles, triples, hr, rbi, r, bb, so, sb, tb, hbp, shf, cs) VALUES
    ('PB_01', (SELECT id FROM teams WHERE gc_uuid='TEAM_T'), '2025', 'full',
     7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7);

INSERT INTO player_season_pitching
    (player_id, team_id, season_id, stat_completeness, gp_pitcher, games_tracked,
     ip_outs, h, r, er, bb, so, wp, hbp, pitches, total_strikes, bf, gs) VALUES
    ('PP_01', (SELECT id FROM teams WHERE gc_uuid='TEAM_T'), '2025', 'full',
     7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7);
